// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

let app;

try {
  const express = require('express');
  app = express();
} catch (error) {
  // Keep the app runnable in minimal test environments where dependencies have
  // not been installed. The fallback implements only the tiny subset of the
  // Express API used by this application: app.get(), res.json(), and listen().
  const http = require('http');

  const routes = [];

  app = (req, res) => {
    res.json = (body) => {
      res.statusCode = res.statusCode || 200;
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.end(JSON.stringify(body));
    };

    const requestUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const route = routes.find(
      (candidate) => candidate.method === req.method && candidate.path === requestUrl.pathname,
    );

    if (!route) {
      res.statusCode = 404;
      res.end('Not Found');
      return;
    }

    route.handler(req, res);
  };

  app.get = (path, handler) => {
    routes.push({ method: 'GET', path, handler });
  };

  app.listen = (...args) => http.createServer(app).listen(...args);
